-- =============================================================================
-- PDI · 0032 · Resultados Saber PRO 2016-2025 (datos iniciales)
--
-- Carga el conjunto Saber PRO del informe Enseñanza con lo que reunió
-- Planeación en "Consolidado saber pro 2016-2024.xlsx":
--
--   · ámbito programa (2016-2024): agregado desde los resultados individuales
--     de la hoja de estudiantes. Sin nombres ni documentos: solo evaluados,
--     promedio, niveles de desempeño y tramos de 10 puntos por sede,
--     facultad, programa y competencia. Los puntajes 0 o "-" (prueba no
--     presentada o anulada) no cuentan. Un programa es sede + nombre, como
--     viene en la fuente; los evaluados sin código SNIES (186 en 2022) no se
--     asignan a ningún programa: quedan en "<programa> · sin código SNIES".
--   · ámbitos institución y nacional (2016-2025): la tabla "Resultados
--     institución" de la hoja Consolidado, tal como la publicó el ICFES.
--     Comunicación escrita 2016 no se carga: no hay resultados individuales
--     ni promedio nacional de ese año en las series históricas.
--
-- Crea el bloque "saber_pro" al final de la ficha si el informe no lo tiene.
-- Se aplica a todo informe con slug "ensenanza". Requiere 0031. Idempotente:
-- reemplaza las filas por programa 2016-2024 y reescribe los promedios.
-- =============================================================================

insert into public.od_saber_pro (report_id, key, title, description, note, office_id, position)
select r.id, 'saber-pro', 'Resultados Saber PRO',
  'Cómo les va a los estudiantes de la UDES en la prueba de Estado de la educación superior, competencia por competencia, frente al promedio del país.',
  'Fuente: ICFES, resultados Saber PRO por evaluado. Un puntaje 0 o sin reporte es una prueba no presentada o anulada y no cuenta. El promedio de toda la universidad es el oficial del ICFES; el de una sede, facultad o programa es el promedio de sus evaluados. El puntaje global no tiene niveles de desempeño.',
  (select o.id from public.od_offices o where o.name = 'Planeación Institucional' limit 1),
  0
from public.od_reports r
where r.slug = 'ensenanza'
on conflict (report_id, key) do nothing;

delete from public.od_saber_pro_results res
using public.od_saber_pro sp, public.od_reports r
where res.saber_id = sp.id and sp.report_id = r.id and r.slug = 'ensenanza' and sp.key = 'saber-pro'
  and res.scope = 'programa' and res.year between 2016 and 2024;

insert into public.od_saber_pro_results
  (saber_id, year, scope, campus, faculty, program, competency, evaluated, mean, levels, histogram)
select sp.id, v.year, v.scope, v.campus, v.faculty, v.program, v.competency, v.evaluated, v.mean, v.levels::jsonb, v.histogram::jsonb
from public.od_saber_pro sp
join public.od_reports r on r.id = sp.report_id and r.slug = 'ensenanza'
